      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Restore saved localStorage
    if (this._savedStorage) {
      for (const [key, value] of Object.entries(this._savedStorage)) {
